const cryptoAssetNameSet = new Set<string>(cryptoAssetNames);

export function resolveCryptoAssetFileName(name: string): string | undefined {
  const trimmed = name.trim();
  if (!trimmed) return undefined;
  if (cryptoAssetNameSet.has(trimmed)) return trimmed;
  if (!trimmed.toLowerCase().startsWith('eds-')) {
    const withPrefix = `eds-${trimmed}`;
    if (cryptoAssetNameSet.has(withPrefix)) return withPrefix;
  }
  return undefined;
}
